//! Gauge lifecycle actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn gauge_lifecycle_actual_app_pointer_clone_import_promotion_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-gauge-lifecycle-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}progress,meter{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}progress[value="3"]{background:#cc2244}meter[value="5"]{background:#2244cc}progress[value="7"]{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><progress id=progress max=10 value=2>Fallback</progress><div id=target></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change gauge</button><div id=destination></div><script>var original=document.getElementById('progress'),target=document.getElementById('target'),held,round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement,watch=new MutationObserver(function(){});watch.observe(target,{childList:true});if(round===0){held=original.cloneNode(true);held.id='copy';held.value=3;original.hidden=true;target.appendChild(held);if(!(held instanceof HTMLProgressElement)||held.value!==3||held.position!==0.3||held.firstChild===original.firstChild||held.textContent!=='Fallback')throw 'native clone';}else if(round===1){target.removeChild(held);var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','meter');source.min=-10;source.max=10;source.value=5;source.appendChild(doc.createTextNode('Imported'));held=document.importNode(source,true);held.id='copy';target.appendChild(held);if(!(held instanceof HTMLMeterElement)||held.value!==5||held.min!==-10||held.optimum!==0||held.textContent!=='Imported'||source.ownerDocument!==doc||source.parentNode!==null)throw 'native import';}else{target.removeChild(held);held=document.createElement('progress');held.id='copy';held.max=10;held.value=7;held.appendChild(document.createTextNode('Promoted'));var attr=held.getAttributeNode('value'),first=held.firstChild,labels=held.labels;target.appendChild(held);if(held.value!==7||held.position!==0.7||held.getAttributeNode('value')!==attr||held.firstChild!==first||held.labels!==labels)throw 'native promotion';}var records=watch.takeRecords();if(held.ownerDocument!==document||held.parentNode!==target||records.length!==(round===0?1:2)||records[records.length-1].addedNodes[0]!==held||original.value!==2||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'lifecycle state';watch.disconnect();document.title='Gauge lifecycle '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("Gauge lifecycle {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
